pub fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    debug_assert_eq!(input.len(), n, "input row count must equal n");
    debug_assert!(j < m, "column index j out of range");

    let mut col = Vec::with_capacity(n);
    for i in 0..n {
        debug_assert_eq!(input[i].len(), m, "each input row must have length m");
        col.push(input[i][j]);
    }
    col
}

pub fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    debug_assert_eq!(input.len(), n, "input row count must equal n");
    for i in 0..n {
        debug_assert_eq!(input[i].len(), m, "each input row must have length m");
    }

    let mut result: Vec<Vec<i8>> = Vec::with_capacity(m);
    for j in 0..m {
        let col_as_row = get_column(&input, j, m, n);
        result.push(col_as_row);
    }
    result
}